Hi, I use the following code to work with pasting of images and files. The original code is pure js, so I just adapted the following code for the editor, putting it inside main.ts.

The code needs to be revised for ts, but as it is it works. It is also already handling drag and drop events.

Hope it helps you.

```
  interface Event {
    clipboardData: any
  }

  container.onpaste = function (event: Event) {
    const items = event.clipboardData.items
    for (const index in items) {
      const item = items[index]
      if (item.kind === 'file') {
        const file = item.getAsFile()
        const fileReader = new FileReader()
        fileReader.readAsDataURL(file)
        fileReader.onload = function () {
          // 计算宽高
          const image = new Image()
          const value = fileReader.result as string
          image.src = value
          image.onload = function () {
            instance.command.executeImage({
              value,
              width: image.width,
              height: image.height
            })
            imageFileDom.value = ''
          }
        }
      }
    }
}
// Optional.   Show the copy icon when dragging over. Seems to only work for chrome.
container.addEventListener('dragover', function (e) {
  if (e) {
      e.stopPropagation()
      e.preventDefault()
      if (e.dataTransfer) {
        e.dataTransfer.dropEffect = 'copy'
      }
  }
})

// Get file data on drop
container.addEventListener('drop', function (e) {
    e.stopPropagation()
    e.preventDefault()
    const files = e?.dataTransfer?.files // Array of all files

    if (files) {
      for (let i = 0; i < files.length; i++) {
        const file = files[i]
        const fileReader = new FileReader()
        fileReader.readAsDataURL(file)
        fileReader.onload = function () {
          // 计算宽高
          const image = new Image()
          const value = fileReader.result as string
          image.src = value
          image.onload = function () {
            instance.command.executeImage({
              value,
              width: image.width,
              height: image.height
            })
            imageFileDom.value = ''
          }
        }
      }
    }
})
