record:

```ts
public record(
    ctx: CanvasRenderingContext2D,
    element: IRowElement,
    x: number,
    y: number
  ) {
    this.ctx = ctx
    const { value, style, color } = element
    // 主动完成的重设起始点
    // if (this.textRenderQueue.length === 0) {
    //   this._setCurXY(x, y)
    // }
    // 样式发生改变
    if (
      (this.curStyle && element.style !== this.curStyle) ||
      element.color !== this.curColor
    ) {
      this.textRenderQueue.push({
        value,
        style,
        color,
        x,
        y
      })
    } else {
      if (this.textRenderQueue.length !== 0) {
        const last = this.textRenderQueue.pop()!
        this.textRenderQueue.push({
          ...last,
          value: (last.value += element.value)
        })
      } else {
        this.textRenderQueue.push({
          value,
          style,
          color,
          x,
          y
        })
      }
    }
    this.curStyle = element.style
    this.curColor = element.color
  }
