paste.ts
````
export function pasteHTML(host: CanvasEvent, htmlText: string) {
  const draw = host.getDraw()
  if (draw.isReadonly() || draw.isDisabled()) return
  const elementList = getElementListByHTML(htmlText, {
    innerWidth: draw.getOriginalInnerWidth()
  })
  processImages(host, elementList)
}

function loadImage(element: IElement): Promise<IElement> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => {
      element.width = img.width;
      element.height = img.height;
      resolve(element);
    };
    img.onerror = () => {
      console.error('Image loading error:', element.value);
      // 可以选择将宽度和高度设置为默认值或者错误值
      reject(new Error(`Image loading error for ${element.value}`));
    };
    img.src = element.value;
  });
}

function processImages(host: CanvasEvent, elementList: IElement[]) {
  const imagePromises: Promise<IElement>[] = elementList
    .filter(element => element.type === ElementType.IMAGE)
    .map(element => loadImage(element));

  // 使用 Promise.all 等待所有的图片加载完成
  Promise.all(imagePromises)
    .then(elements => {
      // 所有图片加载完成，更新 elementList
      elements.forEach(loadedElement => {
        const index = elementList.findIndex(e => e.value === loadedElement.value);
        if (index !== -1) {
          elementList[index] = loadedElement;
        }
      });
      // 调用 pasteElement
      pasteElement(host, elementList);
    })
    .catch(error => {
      console.error('Error loading images:', error);
      // 处理错误情况，可能需要更新 elementList 或通知用户
    });
}
````

